def remove_ads(H, W, grid):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start):
        queue = deque([start])
        visited.add(start)
        min_size = float('inf')
        while queue:
            x, y = queue.popleft()
            min_size = min(min_size, (x - start[0] + 1) * (y - start[1] + 1))
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == '+' and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny))
        return min_size

    visited = set()
    for i in range(1, H-1):
        for j in range(1, W-1):
            if grid[i][j] == '+' and (i, j) not in visited:
                min_size = bfs((i, j))
                if min_size > 9:
                    continue
                for x in range(i-min_size//2, i+min_size//2+1):
                    for y in range(j-min_size//2, j+min_size//2+1):
                        grid[x][y] = ' '

    return [''.join(row) for row in grid]

