def remove_ads(H, W, grid):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(x, y):
        queue = deque([(x, y)])
        visited = set()
        min_size = float('inf')

        while queue:
            cx, cy = queue.popleft()
            if (cx, cy) in visited:
                continue
            visited.add((cx, cy))

            if grid[cx][cy] == '+':
                continue

            min_size = min(min_size, abs(cx - x) * 2 + 1, abs(cy - y) * 2 + 1)

            for dx, dy in directions:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] != '+' and (nx, ny) not in visited:
                    queue.append((nx, ny))

        return min_size

    min_ad_size = float('inf')
    ad_positions = []

    for i in range(1, H - 1):
        for j in range(1, W - 1):
            if grid[i][j] != '+' and grid[i][j] not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789?!., ':
                size = bfs(i, j)
                if size < min_ad_size:
                    min_ad_size = size
                    ad_positions = [(i, j)]
                elif size == min_ad_size:
                    ad_positions.append((i, j))

    for x, y in ad_positions:
        queue = deque([(x, y)])
        visited = set()

        while queue:
            cx, cy = queue.popleft()
            if (cx, cy) in visited:
                continue
            visited.add((cx, cy))
            grid[cx][cy] = ' '

            for dx, dy in directions:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < H and 0 <= ny < W and (nx, ny) not in visited:
                    queue.append((nx, ny))

    result = [''.join(row) for row in grid]
    return ''.join(result)

